//! GameEngine-managed local inference runtime lifecycle for ADR 0155.
//!
//! This module owns machine-local llama.cpp installation, model registration,
//! Windows/WSL execution-environment setup, and demand-driven loopback process
//! lifecycle. It deliberately has no authoring or egui dependency.

use serde::{Deserialize, Serialize};
use std::collections::BTreeSet;
use std::fmt;
use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Write};
use std::net::{IpAddr, Ipv4Addr, SocketAddr, TcpListener, TcpStream};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::mpsc::{self, Receiver, TryRecvError};
use std::thread;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

pub(crate) const MANAGED_BACKEND_ID: &str = "gameengine-managed-llama-cpp";
pub(crate) const MANAGED_LAUNCH_POLICY_VERSION: &str = "adr0155-managed-launch-v1";
pub(crate) const PINNED_LLAMA_CPP_TAG: &str = "b10336";
pub(crate) const PINNED_LLAMA_CPP_REVISION: &str = "f401bb1";
pub(crate) const MANAGED_WSL_DISTRIBUTION: &str = "GameEngine-LocalAI";
const MANAGED_RUNTIME_COMPATIBILITY_VERSION: &str = "llama-server-openai-v1";
const RELEASE_METADATA_URL: &str =
    "https://api.github.com/repos/ggml-org/llama.cpp/releases/tags/b10336";
const STATE_SCHEMA_VERSION: u32 = 1;
const STARTUP_TIMEOUT: Duration = Duration::from_secs(120);
const HEALTH_CONNECT_TIMEOUT: Duration = Duration::from_millis(500);


include!("managed_local_runtime/contracts.rs");
include!("managed_local_runtime/acquisition.rs");
include!("managed_local_runtime/task.rs");
include!("managed_local_runtime/manager_setup.rs");
include!("managed_local_runtime/manager_runtime_install.rs");
include!("managed_local_runtime/manager_remove.rs");
include!("managed_local_runtime/manager_models.rs");
include!("managed_local_runtime/manager_endpoint.rs");
include!("managed_local_runtime/manager_process_launch.rs");
include!("managed_local_runtime/manager_state.rs");
include!("managed_local_runtime/platform_release.rs");
include!("managed_local_runtime/platform_hash.rs");
include!("managed_local_runtime/platform_wsl.rs");
include!("managed_local_runtime/platform_misc.rs");
include!("managed_local_runtime/tests.rs");
